	function GetSoal23(){
		//Paman memiliki kebun jeruk dengan luas 1 hektar. 
		//Setiap 6 bulan, paman dapat memanen jeruk sebanyak 45 kuintal 
		//dan 1 pohon jeruk mampu menghasilkan sekitar 30 kg jeruk. 
		//Agar hasil panen selalu maksimal, 
		//paman memberi pupuk untuk setiap pohon sebanyak 200 gram setiap bulan. 
		//Banyak pupuk yang dibutuhkan paman selama 6 bulan adalah ...
		do{
			var aa = 2*RandomAngkaAtoB(0,6);
			var bb = 5*RandomAngkaAtoB(14,6);
			var cc = 10*RandomAngkaAtoB(0,3);
			var dd = 100*RandomAngkaAtoB(0,3);
			var h1 = aa*bb*dd/(cc*1000);
			var ft = (aa*bb*dd)%cc==0
		}while(dd<1 || !ft)
		
		var ss = "Paman memiliki kebun jeruk dengan luas 1 hektar. ";
		ss += "Setiap "+aa+" bulan, paman dapat memanen jeruk sebanyak "+bb+" kuintal ";
		ss += "dan 1 pohon jeruk mampu menghasilkan sekitar "+cc+" kg jeruk. ";
		ss += "Agar hasil panen selalu maksimal, ";
		ss += "paman memberi pupuk untuk setiap pohon sebanyak "+dd+" gram setiap bulan. ";
		ss += "Banyak pupuk yang dibutuhkan paman selama "+aa+" bulan adalah ...";
		
		var ar_er = [];
		for(var i=-10;i<=10;i++){
			if(i!==0) ar_er.push(i);
		}
		do{
			ar_er=RandomMyArray(ar_er);
			
			var Ar = [];
			Ar[0] = h1;
			Ar[1] = h1+ar_er[0]; 
			Ar[2] = h1+ar_er[1]; 
			Ar[3] = h1+ar_er[2]; 
		}while(Ar[1]<=0 || Ar[2]<=0 || Ar[3]<=0)
		
		for(var i=0;i<4;i++){
			Ar[i]=StringDesimal(Math.round(Ar[i]*10)/10);
		}
		
		var jawab = Ar[0];
		Ar=RandomMyArray(Ar);
		
		var noBenar = NoJawabanBenar(Ar, jawab);
		var textSoal = ss+" <p>A. "+Ar[0]+" kg<br>B. "+Ar[1]+" kg<br>C. "+Ar[2]+" kg<br>D. "+Ar[3]+" kg</p>";
		
		var ArFix = [];
		ArFix.push(textSoal);
		ArFix.push(GetABCD(noBenar));
		
		return ArFix;
	}
